//! App Logo 专属矢量与位图静态数据（圆角透明抗锯齿专属小鸟微标）

pub const APP_LOGO_DATA_URI: &str = "data:image/png;base64,";

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_logo_data_uri_valid() {
        assert!(APP_LOGO_DATA_URI.starts_with("data:image/png;base64,"));
        assert!(APP_LOGO_DATA_URI.contains("iVBORw0KGgo"));
    }
}
